import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry and material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture for the plane
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply cinematic primitives
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const inst = ctx.primitives[p.name](root, p.params);
    primitiveInstances.push(inst);
  }

  // Event handlers storage
  const handlers = {};

  // Hover lift (rise‑in) effect
  const hoverIn = gsap.timeline({ paused: true });
  hoverIn.to(root.position, { y: '+=0.15', duration: 0.3, ease: 'power2.out' });

  const hoverOut = gsap.timeline({ paused: true });
  hoverOut.to(root.position, { y: '-=0.15', duration: 0.2, ease: 'power2.in' });

  handlers.hover = {
    enter: () => {
      hoverOut.pause(0);
      hoverIn.play(0);
    },
    leave: () => {
      hoverIn.pause(0);
      hoverOut.play(0);
    },
  };

  // Click emit handler
  handlers.click = () => {
    ctx.emit('hub-pricing.select');
  };

  root.userData.handlers = handlers;

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Kill GSAP timelines
    hoverIn.kill();
    hoverOut.kill();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
  };

  return root;
}
